CREATE COLUMN TABLE "TEST_AP"."ODCI" ("AbsEntry" INTEGER CS_INT NOT NULL , "ConfType" NVARCHAR(1), "Code" NVARCHAR(50), "Descr" NVARCHAR(254), "PrcstVal" DECIMAL(21,6) CS_FIXED, "SuppUnit" INTEGER CS_INT, "Export" NVARCHAR(1) DEFAULT 'Y', "Import" NVARCHAR(1) DEFAULT 'Y', "StatCode" NVARCHAR(2), "DateFrom" LONGDATE CS_LONGDATE, "DateTo" LONGDATE CS_LONGDATE, "TextVal" NVARCHAR(12), "ConfID" NVARCHAR(254), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "ODCI_CONF_ID" ON "TEST_AP"."ODCI" ( "ConfID" ASC )